const Hero: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const headlineRef = useRef<HTMLHeadingElement>(null);
  const subRef = useRef<HTMLParagraphElement>(null);
  const [timeLeft, setTimeLeft] = useState('23:59:59');

  useEffect(() => {
    // Countdown Logic
    const timer = setInterval(() => {
      const date = new Date();
      const hours = 23 - date.getHours();
      const minutes = 59 - date.getMinutes();
      const seconds = 59 - date.getSeconds();
      setTimeLeft(
        `${hours.toString().padStart(2, '0')}:${minutes
          .toString()
          .padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`
      );
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const ctx = gsap.context(() => {
      // Timeline for initial load
      const tl = gsap.timeline();

      tl.fromTo(
        headlineRef.current,
        { y: 100, opacity: 0, rotateX: 10 },
        { y: 0, opacity: 1, rotateX: 0, duration: 1.2, ease: 'power4.out' }
      )
        .fromTo(
          subRef.current,
          { y: 30, opacity: 0 },
          { y: 0, opacity: 1, duration: 0.8, ease: 'power2.out' },
          '-=0.8'
        )
        .fromTo(
          '.hero-btn',
          { y: 20, opacity: 0 },
          { y: 0, opacity: 1, stagger: 0.1, duration: 0.6, ease: 'back.out(1.7)' },
          '-=0.6'
        );

      // Parallax effect on scroll
      gsap.to('.hero-bg-gradient', {
        yPercent: 30,
        ease: 'none',
        scrollTrigger: {
          trigger: containerRef.current,
          start: 'top top',
          end: 'bottom top',
          scrub: true,
        },
      });
    }, containerRef);

    return () => ctx.revert();
  }, []);

  const scrollToCourses = () => {
    const element = document.getElementById('courses-section');
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <div ref={containerRef} className="relative min-h-[90vh] flex flex-col pt-20 overflow-hidden bg-brand-black">
      {/* Background Effects */}
      <div className="absolute inset-0 z-0">
        {/* Box Grid Background */}
        <div className="absolute inset-0 bg-[linear-gradient(to_right,#ffffff0a_1px,transparent_1px),linear-gradient(to_bottom,#ffffff0a_1px,transparent_1px)] bg-[size:40px_40px] [mask-image:radial-gradient(ellipse_60%_50%_at_50%_0%,#000_70%,transparent_100%)]"></div>

        {/* Animated Blobs */}
        <div className="hero-bg-gradient absolute top-[-20%] left-[-10%] w-[50%] h-[50%] bg-brand-blue rounded-full blur-[150px] opacity-10 pointer-events-none" />
        <div className="hero-bg-gradient absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-purple-900 rounded-full blur-[120px] opacity-10 pointer-events-none" />
      </div>

      {/* Urgency Bar */}
      <div className="w-full bg-brand-blue/10 border-b border-brand-blue/20 backdrop-blur-md py-2 flex justify-center items-center gap-3 z-50 fixed top-0 left-0">
        <span className="text-brand-blue text-sm font-semibold animate-pulse">🎬 Registration Closing Soon</span>
        <span className="text-gray-300 text-xs md:text-sm">Next Batch Starts in <span className="font-mono font-bold text-white">{timeLeft}</span></span>
      </div>

      <div className="container mx-auto px-4 lg:px-8 flex flex-col items-center justify-center flex-grow z-10 mt-32 relative pb-20">
        {/* Content */}
        <div className="max-w-4xl mx-auto text-center space-y-8">
          <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-white/5 border border-white/10 text-sm text-gray-300 mb-4 backdrop-blur-sm">
            <span className="w-2 h-2 rounded-full bg-brand-blue animate-pulse"></span>
            Tamil Creators Academy
          </div>

          <h1 ref={headlineRef} className="mt-8 font-serif text-5xl md:text-7xl lg:text-8xl leading-[1.1] text-transparent bg-clip-text bg-gradient-to-b from-white to-gray-400 italic">
            Master the art of <br />
            <span className="not-italic text-white">Digital Storytelling.</span>
          </h1>

          <p ref={subRef} className="text-lg md:text-xl text-gray-400 max-w-2xl mx-auto font-sans leading-relaxed">
            From viral <span className="text-white font-medium">Reels</span> to cinematic <span className="text-white font-medium">Films</span>. 
            Join the #1 editing community in Tamil Nadu and turn your creative passion into a high-paying career.
          </p>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-4 pt-8">
            <button 
              onClick={scrollToCourses}
              className="hero-btn group relative px-8 py-4 bg-brand-blue text-white font-semibold rounded-full overflow-hidden hover:shadow-[0_0_30px_-5px_rgba(26,193,221,0.6)] transition-all duration-300"
