      gsap.fromTo(lineRef.current, 
        { height: '0%' },
        {
          height: '100%',
          ease: 'none',
          scrollTrigger: {
            trigger: '.timeline-container',
            start: 'top 60%',
            end: 'bottom 80%',
            scrub: 1,
          }
        }
      );

      // Timeline Items Animation
      const items = gsap.utils.toArray('.timeline-item');
      items.forEach((item: any, index) => {
        gsap.fromTo(item,
          { opacity: 0, x: 50, filter: 'blur(10px)' },
          {
            opacity: 1,
            x: 0,
            filter: 'blur(0px)',
