          </div>

          <h1 ref={headlineRef} className="mt-8 font-serif">
            {/* First Line: Tamil Editing */}
            <span className="block text-5xl md:text-7xl lg:text-8xl text-transparent bg-clip-text bg-gradient-to-b from-white to-gray-400 italic tracking-wide mb-2 md:mb-4">
               Tamil Editing
            </span>
            {/* Second Line: SCHOOL (Big) */}
            <span className="block text-7xl md:text-9xl lg:text-[180px] leading-[0.8] text-white not-italic font-medium tracking-tighter">
               SCHOOL
            </span>
          </h1>

          <p ref={subRef} className="text-lg md:text-xl text-gray-400 max-w-2xl mx-auto font-sans leading-relaxed pt-6">
            From viral <span className="text-white font-medium">Reels</span> to cinematic <span className="text-white font-medium">Films</span>. 
            Join the #1 editing community in Tamil Nadu and turn your creative passion into a high-paying career.
          </p>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-4 pt-8">
            <button 
