            <span className="font-medium text-sm">Back to Hub</span>
        </button>
      </header>

      {/* Hero Section - Redesigned to match Main Page */}
      <section className="relative min-h-[95vh] flex flex-col pt-0 overflow-hidden bg-brand-black">
        {/* Background Effects */}
