import React, { useEffect, useState, Suspense } from 'react';
import Hero from './components/Hero';
import HowItWorks from './components/HowItWorks';
import TrustedBy from './components/TrustedBy';
import Courses from './components/Courses';
import Footer from './components/Footer';

// Lazy load the CapCut page to reduce initial bundle size
const CapCutPage = React.lazy(() => import('./components/CapCutPage'));

// Loading fallback for the lazy component
const PageLoader = () => (
  <div className="min-h-screen bg-brand-black flex items-center justify-center">
    <div className="flex flex-col items-center gap-4">
      <div className="w-12 h-12 border-4 border-white/10 border-t-brand-blue rounded-full animate-spin"></div>
      <p className="text-gray-400 text-sm font-mono animate-pulse">Loading Course Data...</p>
    </div>
  </div>
);

const App: React.FC = () => {
  // Simple state-based routing
  const [currentView, setCurrentView] = useState<'home' | 'capcut'>('home');
  // Lifted modal state to App level so Footer can trigger it
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    // Smooth scroll behavior for anchor links
    document.documentElement.style.scrollBehavior = 'smooth';

    // --- ROUTING LOGIC START ---
    // This fixes the issue where deep links or subdomains wouldn't load the CapCut page
    const handleRouting = () => {
      const params = new URLSearchParams(window.location.search);
      const pageParam = params.get('page');
      const hash = window.location.hash;
      const hostname = window.location.hostname;

      // Check for ?page=capcut OR #capcut OR subdomain 'capcut.'
      if (
        pageParam === 'capcut' || 
        hash === '#capcut' || 
        hostname.startsWith('capcut.')
      ) {
        setCurrentView('capcut');
      } else {
        // Only revert to home if explicitly navigating back or loading root
        if (pageParam !== 'capcut' && hash !== '#capcut' && !hostname.startsWith('capcut.')) {
             setCurrentView('home');
        }
      }
    };

    // Run on mount
    handleRouting();

    // Run on back/forward button
    window.addEventListener('popstate', handleRouting);
    return () => window.removeEventListener('popstate', handleRouting);
    // --- ROUTING LOGIC END ---
  }, []);

  // Helper to update URL without page reload
  const updateUrl = (view: 'home' | 'capcut') => {
    const newUrl = new URL(window.location.href);
    if (view === 'capcut') {
      newUrl.searchParams.set('page', 'capcut');
    } else {
      newUrl.searchParams.delete('page');
    }
    // Push state so back button works
    window.history.pushState({}, '', newUrl);
  };

  const handleCourseSelection = (courseId: string) => {
    if (courseId === 'capcut') {
      setCurrentView('capcut');
      updateUrl('capcut');
      window.scrollTo(0, 0);
    }
    // Future: Handle other course IDs
  };

  const handleBackToHome = () => {
    setCurrentView('home');
    setIsModalOpen(false);
    updateUrl('home');
    window.scrollTo(0, 0);
  };

  const handleFooterEnroll = () => {
    setCurrentView('capcut');
    setIsModalOpen(true);
    updateUrl('capcut');
    window.scrollTo(0, 0);
  };

  return (
    <div className="font-sans bg-brand-black text-white selection:bg-brand-blue selection:text-white">
      <main className="relative overflow-hidden">
        {currentView === 'home' ? (
          <>
            <Hero />
            {/* Moved TrustedBy to second position as requested */}
            <TrustedBy />
            <Courses onSelectCourse={handleCourseSelection} />
            <HowItWorks />
          </>
        ) : (
          <Suspense fallback={<PageLoader />}>
            <CapCutPage 
              onBack={handleBackToHome} 
              isModalOpen={isModalOpen}
              setIsModalOpen={setIsModalOpen}
            />
          </Suspense>
        )}
      </main>
      <Footer onEnroll={handleFooterEnroll} />
    </div>
  );
};

export default App;

