const CapCutPage: React.FC<CapCutPageProps> = ({ onBack, isModalOpen, setIsModalOpen }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const headlineRef = useRef<HTMLHeadingElement>(null);
  const subRef = useRef<HTMLParagraphElement>(null);
  const lineRef = useRef<HTMLDivElement>(null);
  const curriculumRef = useRef<HTMLDivElement>(null);
  const certificateRef = useRef<HTMLDivElement>(null);
  const pricingRef = useRef<HTMLDivElement>(null);

  const [timeLeft, setTimeLeft] = useState('06:00:00');
  const [isScrolled, setIsScrolled] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', phone: '' });

  useEffect(() => {
    // Scroll to top on mount
    window.scrollTo(0, 0);

    // Scroll Handler for Sticky Header
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 100);
    };
    window.addEventListener('scroll', handleScroll);

    // Countdown Logic (6 Hour Cycles)
    const updateTimer = () => {
      const date = new Date();
      // Calculate remaining time in a 6-hour window (0-6, 6-12, 12-18, 18-24)
      const currentHour = date.getHours();
      const remainingHours = 5 - (currentHour % 6);
      const remainingMinutes = 59 - date.getMinutes();
      const remainingSeconds = 59 - date.getSeconds();

      setTimeLeft(
        `${remainingHours.toString().padStart(2, '0')}:${remainingMinutes
          .toString()
          .padStart(2, '0')}:${remainingSeconds.toString().padStart(2, '0')}`
      );
    };

    // Initial call
    updateTimer();

    const timer = setInterval(updateTimer, 1000);

    const ctx = gsap.context(() => {
        // 1. Hero Animation Sequence
        const tl = gsap.timeline();

        tl.fromTo(
            '.hero-tagline',
            { y: 20, opacity: 0 },
            { y: 0, opacity: 1, duration: 0.8, ease: 'power2.out' }
        )
        .fromTo(
            headlineRef.current,
            { y: 50, opacity: 0, scale: 0.95 },
            { y: 0, opacity: 1, scale: 1, duration: 1.2, ease: 'power3.out' },
            '-=0.4'
        )
        .fromTo(
            subRef.current,
            { y: 30, opacity: 0 },
            { y: 0, opacity: 1, duration: 0.8, ease: 'power2.out' },
            '-=0.8'
        )
        .fromTo(
            '.wistia-embed',
            { y: 40, opacity: 0, scale: 0.95 },
            { y: 0, opacity: 1, scale: 1, duration: 1, ease: 'power3.out' },
            '-=0.4'
        )
        .fromTo(
            '.hero-btn',
            { y: 20, opacity: 0 },
            { y: 0, opacity: 1, stagger: 0.1, duration: 0.6, ease: 'back.out(1.7)' },
            '-=0.6'
        );

        // Parallax effect on scroll
        gsap.to('.hero-bg-gradient', {
            yPercent: 30,
            ease: 'none',
            scrollTrigger: {
            trigger: containerRef.current,
            start: 'top top',
            end: 'bottom top',
            scrub: true,
            },
        });

        // 2. Timeline Line Animation
        gsap.fromTo(lineRef.current, 
            { height: '0%' },
            {
              height: '100%',
              ease: 'none',
              scrollTrigger: {
                trigger: '.cc-timeline-container',
                start: 'top 60%',
                end: 'bottom 80%',
                scrub: 1,
              }
            }
        );

        // 3. Timeline Items Animation
        const items = gsap.utils.toArray('.cc-timeline-item');
        items.forEach((item: any, index) => {
            gsap.fromTo(item,
            { opacity: 0, x: 30, filter: 'blur(5px)' },
            {
                opacity: 1,
                x: 0,
                filter: 'blur(0px)',
                duration: 0.6,
                ease: 'power3.out',
                scrollTrigger: {
                    trigger: item,
                    start: 'top 85%', 
                    toggleActions: 'play none none reverse'
                }
            });
        });

        // 4. Certificate Animation
        if (certificateRef.current) {
            gsap.from(certificateRef.current.children, {
                y: 50,
                opacity: 0,
                stagger: 0.2,
                duration: 0.8,
                ease: 'power3.out',
                scrollTrigger: {
                    trigger: certificateRef.current,
                    start: 'top 70%',
                }
            });
        }

        // 6. Pricing Card Animation
        gsap.from(pricingRef.current, {
            y: 50,
            opacity: 0,
            scale: 0.95,
            duration: 0.8,
            ease: 'power3.out',
            scrollTrigger: {
                trigger: pricingRef.current,
                start: 'top 85%',
            }
        });

    }, containerRef);

    return () => {
        ctx.revert();
        clearInterval(timer);
        window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  const handleEnrollClick = () => {
    setIsModalOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Simulate submission
    console.log("Form Submitted:", formData);
    alert("Thanks for enrolling! We will contact you shortly to finalize the payment.");
    setIsModalOpen(false);
    setFormData({ name: '', email: '', phone: '' });
  };

  const [hours, minutes, seconds] = timeLeft.split(':');

